import os, json, time
import numpy as np

AUDIT_SLACK = 'storage/noesis/nmap/results/noesis_internal_topk_audit.json'
AUDIT_KKT   = 'storage/noesis/nmap/results/noesis_internal_kkt_topk_audit.json'
OUT_DIR     = 'storage/noesis/nmap/results'
FREEZE_DIR  = 'storage/noesis/nmap/freezes'
SNAP_C      = 'storage/noesis/latest_centers.txt'
SNAP_R      = 'storage/noesis/latest_radii.txt'

K_GRID = [15, 25, 40, 60]
TOLS = [1e-9, 1e-8]
N = 26

def load_json(path):
    with open(path, 'r') as f:
        return json.load(f)

def pairs_to_set(pairs):
    S = set()
    for p in pairs:
        try:
            i, j = int(p[0]), int(p[1])
            if i == j: continue
            if i > j: i, j = j, i
            S.add((i, j))
        except Exception:
            continue
    return S

def jaccard(A, B):
    if not A and not B: return 1.0, 0, 0
    if not A or not B: return 0.0, 0, len(A|B)
    inter = len(A & B); uni = len(A | B)
    return (inter/uni if uni > 0 else 1.0), inter, uni

def compute_overlap(slack_audit, kkt_audit):
    out = []
    for tol in TOLS:
        tol_key = str(tol)
        for K in K_GRID:
            K_key = str(K)
            try:
                S_slack = pairs_to_set(slack_audit['topk_pairs'][tol_key][K_key])
            except Exception:
                S_slack = set()
            try:
                S_kkt = pairs_to_set(kkt_audit['topk_pairs'][tol_key][K_key])
            except Exception:
                S_kkt = set()
            j, inter, uni = jaccard(S_slack, S_kkt)
            out.append({
                'tol': tol,
                'K': K,
                'slack_size': len(S_slack),
                'kkt_size': len(S_kkt),
                'jaccard': j,
                'intersection': inter,
                'union': uni
            })
    return out

def write_json(path, obj):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w') as f:
        json.dump(obj, f, indent=2)

def load_snapshot():
    if os.path.exists(SNAP_C) and os.path.exists(SNAP_R):
        c = np.loadtxt(SNAP_C, dtype=float).reshape(N, 2)
        r = np.loadtxt(SNAP_R, dtype=float).reshape(N,)
        return c, r
    # conservative fallback
    centers = []
    radius = 0.08
    for i in range(5):
        for j in range(6):
            if len(centers) < N:
                centers.append([0.1 + 0.2*i, 0.1 + 0.15*j])
    return np.array(centers, float), np.full(N, radius, float)

def construct_packing():
    # analysis
    try:
        slack_audit = load_json(AUDIT_SLACK)
    except Exception:
        slack_audit = {}
    try:
        kkt_audit = load_json(AUDIT_KKT)
    except Exception:
        kkt_audit = {}
    rows = compute_overlap(slack_audit, kkt_audit)
    now = time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())
    report = {
        'generated_at': now,
        'k_grid': K_GRID,
        'tols': TOLS,
        'rows': rows
    }
    write_json(os.path.join(OUT_DIR, 'noesis_cross_method_topk_overlap.json'), report)
    write_json(os.path.join(FREEZE_DIR, f'noesis_cross_method_topk_overlap_{now}.json'), report)

    # return baseline
    c0, r0 = load_snapshot()
    r = np.maximum(r0 - 1e-9, 1e-12)
    return c0.astype(float), r.astype(float)
